                  </Reveal>
                  </details>
                </>
              )}

              {/* ── AGENTS TAB: agent activation, performance, login hours, live monitor ── */}
              {dashTab === 'agents' && (
                <>
                  {rosterAttendance.length > 0 && (() => {
