                              const statusClass = c.queue === 'fire_transfer' ? 'rpc-transfer' : c.queue === 'human_drop' ? 'rpc-human' : c.queue === 'no_answer' ? 'rpc-noans' : c.queue === 'voice_message' ? 'rpc-vm' : c.queue === 'pending' ? 'rpc-dialing' : 'rpc-other';
