                                  <span className="rpc-status">{statusLabel}</span>
                                  <span className="rpc-duration">{c.duration_seconds > 0 ? `${Math.round(c.duration_seconds)}s` : '—'}</span>
                                </div>
                              );
                            })}
                          </div>
