vi.mock('@/modules/monitoring/api', () => ({canMonitor: () => true, useMonitoringAttendance: () => {}}));
vi.mock('@/modules/monitoring/AgentMonitoring', () => ({AgentMonitoring: () => <span>Monitoring</span>}));
import App from '../src/App';

beforeEach(() => {
  state.model = { session: { valid: true, agent: { id: 'test-agent', full_name: 'Test Agent' } }, sessionToken: 'test-only', isOwner: false, isStrictOwner: false, ownerNeedsSetup: false, activeNav: 'dashboard', atomicLogout: vi.fn() };
  state.crashWorkspace = state.crashChat = false;
  state.mounted = { phone: 0, chat: 0, camera: 0 };
  state.unmounted = { phone: 0, chat: 0, camera: 0 };
});

describe('persistent communication modules', () => {
  it('keeps one phone, chat and camera mounted across page changes and token renewal', () => {
    let root: ReturnType<typeof create>;
    act(() => { root = create(<App />); });
    for (const activeNav of ['contacts', 'calls', 'saved', 'monitoring', 'inbox', 'dashboard']) {
      state.model = { ...state.model, activeNav, sessionToken: 'renewed-test-only' };
      act(() => root.update(<App />));
    }
    expect(state.mounted).toEqual({ phone: 1, chat: 1, camera: 1 });
    expect(state.unmounted).toEqual({ phone: 0, chat: 0, camera: 0 });
    act(() => root.unmount());
  });

  it('contains a workspace rendering failure without unmounting communications', () => {
    const consoleError = vi.spyOn(console, 'error').mockImplementation(() => {});
    let root: ReturnType<typeof create>;
    act(() => { root = create(<App />); });
    state.crashWorkspace = true;
    act(() => root.update(<App />));
    expect(root!.root.findAllByProps({ role: 'alert' })).toHaveLength(1);
    expect(state.mounted.phone).toBe(1);
    expect(state.unmounted).toEqual({ phone: 0, chat: 0, camera: 0 });
    state.crashWorkspace = false;
    act(() => root.root.findByProps({ className: 'secondary-button' }).props.onClick());
    expect(root!.root.findAllByProps({ role: 'alert' })).toHaveLength(0);
    act(() => root.unmount());
    consoleError.mockRestore();
  });

  it('contains a chat failure without restarting phone or camera', () => {
    const consoleError = vi.spyOn(console, 'error').mockImplementation(() => {});
    let root: ReturnType<typeof create>;
    act(() => { root = create(<App />); });
    state.crashChat = true;
    act(() => root.update(<App />));
    expect(state.unmounted.phone).toBe(0);
    expect(state.unmounted.camera).toBe(0);
    act(() => root.unmount());
    consoleError.mockRestore();
  });

  it('unmounts all communication modules at logout', () => {
    let root: ReturnType<typeof create>;
    act(() => { root = create(<App />); });
    state.model = { ...state.model, session: null, sessionToken: '' };
    act(() => root.update(<App />));
    expect(state.unmounted).toEqual({ phone: 1, chat: 1, camera: 1 });
    expect(root!.toJSON()).toEqual({ type: 'span', props: {}, children: ['Sign in'] });
    act(() => root.unmount());
  });

  it('does not mount an agent phone for the owner', () => {
    state.model = { ...state.model, isOwner: true, isStrictOwner: true };
    let root: ReturnType<typeof create>;
    act(() => { root = create(<App />); });
    expect(state.mounted).toEqual({ phone: 0, chat: 1, camera: 1 });
    act(() => root.unmount());
  });
});

import React from 'react';
import { act, create } from 'react-test-renderer';
import { afterEach, beforeEach, expect, it, vi } from 'vitest';
import * as shared from '../src/app/shared';
import { useLoginLifecycle, useLoginState } from '../src/modules/login/useLoginSession';

let current: ReturnType<typeof useLoginState> & ReturnType<typeof useLoginLifecycle>;
const onLogout = vi.fn();
function Harness() {
  const login = useLoginState();
  const lifecycle = useLoginLifecycle({ ...login, setAgentAvailable: vi.fn(), setActiveNav: vi.fn(), setShowOfflineModal: vi.fn(), atomicLogout: onLogout });
  current = { ...login, ...lifecycle };
  return null;
}
const response = (data: unknown, status = 200) => new Response(JSON.stringify(data), { status });
let root: ReturnType<typeof create> | undefined;
let saved: Map<string, string>;
beforeEach(() => {
  saved = new Map();
  onLogout.mockClear();
  vi.stubGlobal('localStorage', { getItem: (key: string) => saved.get(key) ?? null, setItem: (key: string, value: string) => saved.set(key, value), removeItem: (key: string) => saved.delete(key) });
  vi.stubGlobal('window', { location: { search: '', pathname: '/' }, addEventListener: vi.fn(), removeEventListener: vi.fn(), history: { replaceState: vi.fn() } });
});
afterEach(() => { if (root) act(() => root!.unmount()); root = undefined; vi.restoreAllMocks(); vi.unstubAllGlobals(); });

it('restores a valid saved login through the unchanged verify action', async () => {
  saved.set('sterling_session_token', 'synthetic-saved-session');
  const request = vi.spyOn(shared, 'fetchWithRetry').mockImplementation(async (_url, body) => response(body.action === 'verify' ? { valid: true, agent: { id: 'test-agent', role: 'agent', available_for_transfer: true } } : { needs_setup: false }));
  await act(async () => { root = create(<Harness />); });
  expect(current.session?.valid).toBe(true);
  expect(current.sessionToken).toBe('synthetic-saved-session');
  expect(request).toHaveBeenCalledWith(shared.AUTH_URL, { action: 'verify', session_token: 'synthetic-saved-session' }, 1, 25000);
});

it('keeps a saved login during a temporary verification outage', async () => {
  saved.set('sterling_session_token', 'synthetic-saved-session');
  vi.spyOn(shared, 'fetchWithRetry').mockImplementation(async (_url, body) => { if (body.action === 'verify') throw new Error('temporary network outage'); return response({ needs_setup: false }); });
  await act(async () => { root = create(<Harness />); });
  expect(saved.get('sterling_session_token')).toBe('synthetic-saved-session');
  expect(current.session).toBe(null);
  expect(current.loginError).toContain('Reconnecting');
});

it('clears explicitly expired saved authorization', async () => {
  saved.set('sterling_session_token', 'synthetic-expired-session');
  vi.spyOn(shared, 'fetchWithRetry').mockImplementation(async (_url, body) => response(body.action === 'verify' ? { valid: false } : { needs_setup: false }));
  await act(async () => { root = create(<Harness />); });
  expect(saved.has('sterling_session_token')).toBe(false);
  expect(current.loginError).toContain('Session expired');
});

it('rejects incomplete PINs locally and logs out even if the server is unavailable', async () => {
  const request = vi.spyOn(shared, 'fetchWithRetry').mockResolvedValue(response({ needs_setup: false }));
  await act(async () => { root = create(<Harness />); });
  await act(async () => { await current.handleLogin('12'); });
  expect(current.loginError).toBe('PIN must be 4 digits');
  expect(request).toHaveBeenCalledTimes(1);
  vi.stubGlobal('fetch', vi.fn().mockRejectedValue(new Error('offline')));
  await act(async () => { await current.handleLogout(); });
  expect(onLogout).toHaveBeenCalledTimes(1);
});

import { afterEach, expect, it, vi } from 'vitest';
import { startSerialPoll } from '../src/utils/serial-poll';
import { refreshWorkspace, workspaceReads, type WorkspaceRead } from '../src/utils/workspace-refresh';
afterEach(() => vi.useRealTimers());

it('loads only the visible owner reports and retains agent transfer alerts', () => {
  expect(workspaceReads(true, 'dashboard', 'overview')).toEqual(['admin']);
  expect(workspaceReads(true, 'leads', 'overview')).toEqual(['leads']);
  expect(workspaceReads(true, 'monitoring', 'overview')).toEqual([]);
  expect(workspaceReads(true, 'system', 'redial')).toEqual(['admin', 'redial', 'team']);
  expect(workspaceReads(false, 'dashboard', 'overview')).toEqual(['queues', 'alerts', 'transfers']);
  expect(workspaceReads(false, 'saved', 'overview')).toContain('saved');
  expect(workspaceReads(false, 'dashboard', 'overview')).not.toContain('secretary');
});

it('shows the primary report first and cancels the old page before its next report', async () => {
  const controller = new AbortController();
  const order: string[] = [];
  const loaders = Object.fromEntries(['admin', 'team', 'redial'].map(name => [name, async () => {
    order.push(name); if (name === 'admin') controller.abort(); return true;
  }])) as Record<WorkspaceRead, (signal: AbortSignal) => Promise<boolean>>;
  expect(await refreshWorkspace(['admin', 'redial', 'team'], loaders, controller.signal)).toBe(false);
  expect(order).toEqual(['admin']);
});

it('a failed agent statistics query does not suppress transfer alerts', async () => {
  const alerts = vi.fn(async () => true), transfers = vi.fn(async () => true);
  const loaders = { queues: async () => false, alerts, transfers } as unknown as Record<WorkspaceRead, (signal: AbortSignal) => Promise<boolean>>;
  expect(await refreshWorkspace(['queues', 'alerts', 'transfers'], loaders, new AbortController().signal, false)).toBe(false);
  expect(alerts).toHaveBeenCalledOnce(); expect(transfers).toHaveBeenCalledOnce();
});

it('never overlaps slow refreshes and backs off after failures', async () => {
  vi.useFakeTimers();
  let release!: (ok: boolean) => void;
  const task = vi.fn(() => new Promise<boolean>(resolve => { release = resolve; }));
  const poll = startSerialPoll(task, 30000, { maxBackoffMs: 120000 });
  await vi.advanceTimersByTimeAsync(90000);
  poll.refresh(); expect(task).toHaveBeenCalledTimes(1);
  release(false); await vi.advanceTimersByTimeAsync(59999);
  expect(task).toHaveBeenCalledTimes(1);
  await vi.advanceTimersByTimeAsync(1); expect(task).toHaveBeenCalledTimes(2);
  poll.stop(); release(true);
  await vi.advanceTimersByTimeAsync(300000); expect(task).toHaveBeenCalledTimes(2);
});

it('pauses hidden reports and resumes with one request; cleanup aborts in-flight work', async () => {
  vi.useFakeTimers(); let hidden = true;
  const task = vi.fn(async () => true);
  const poll = startSerialPoll(task, 30000, { paused: () => hidden });
  await vi.advanceTimersByTimeAsync(60000); expect(task).not.toHaveBeenCalled();
  hidden = false; poll.refresh(); await vi.advanceTimersByTimeAsync(0);
  expect(task).toHaveBeenCalledTimes(1); poll.stop();
  let observed: AbortSignal | undefined;
  const active = startSerialPoll(signal => { observed = signal; return new Promise(() => {}); }, 30000);
  active.stop(); expect(observed?.aborted).toBe(true);
});

// Local release gate only. Never logs in, contacts a customer or activates calls.
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';

const protectedFiles = JSON.parse(readFileSync(new URL('./phone-baseline.json', import.meta.url), 'utf8'));
for (const [path, expected] of Object.entries(protectedFiles)) {
  const actual = createHash('sha256').update(readFileSync(path)).digest('hex');
  if (actual !== expected) throw new Error(`Phone isolation gate failed: ${path} changed. Review before release.`);
}
for (const args of [
  ['node_modules/typescript/bin/tsc', '--noEmit', '-p', 'tsconfig.app.json'],
  ['node_modules/vitest/vitest.mjs', 'run', '--config', 'vitest.stability.config.ts'],
  ['node_modules/vite/bin/vite.js', 'build'],
]) {
  const result = spawnSync(process.execPath, args, { stdio: 'inherit' });
  if (result.status !== 0) process.exit(result.status ?? 1);
}
console.log('Stability gate passed. Publication and real-device checks remain separate.');

